package com.elendheim.codex.codex.repo

// Four small placeholder pictures, framed image icons in muted gray on the dark
// surface color, each with a corner number so it is obvious which one you are on
// when swiping. The example entries ship with these so the picture feature and the
// swipe viewer are visible right away. They are plain PNGs stored as base64, exactly
// like any image you add yourself, so they export, import and can be replaced freely.
object SeedImages {
    const val image1: String =
        ""
    const val image2: String =
        ""
    const val image3: String =
        ""
    const val image4: String =
        ""

    // The first image is the cover, the other three are additional views.
    val defaultGallery: List<String> = listOf(image1, image2, image3, image4)

    // Kept for older references that expect a single placeholder.
    const val placeholder: String = image1
}
